class Solution {
public:
    int numWays(int steps, int arrLen) {
        const int MOD = 1000000007;
        int n = min(arrLen, steps / 2 + 1);
        vector<long long> dp(n, 0), next(n, 0);
        dp[0] = 1;
        for (int s = 0; s < steps; s++) {
            fill(next.begin(), next.end(), 0);
            for (int j = 0; j < n; j++) {
                if (dp[j] == 0) continue;
                next[j] = (next[j] + dp[j]) % MOD;
                if (j + 1 < n) next[j + 1] = (next[j + 1] + dp[j]) % MOD;
                if (j - 1 >= 0) next[j - 1] = (next[j - 1] + dp[j]) % MOD;
            }
            swap(dp, next);
        }
        return dp[0];
    }
};
